/**
 * Every matching row, newest first, with no page cap. The audit export uses
 * this so a long window is not truncated to the feed's page size.
 */
export async function listAllActivity(
  input: Omit<ActivityFilterInput, "limit" | "cursor">,
): Promise<readonly ActivityEvent[]> {
  const rows = getDb()
    .select()
    .from(activityEvents)
    .where(and(...activityFilters(input)))
    .orderBy(desc(activityEvents.occurredAt), desc(activityEvents.id))
    .all();

  return rows.map(toActivityEvent);
}

