/** The project an issue belongs to, so comment rows survive a project filter. */
async function projectIdForIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<ProjectId | null> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  return issue?.projectId ?? null;
}

