import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { toIsoTimestamp } from "@/types/common";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as projectService from "@/server/services/project-service";
import * as memberService from "@/server/services/member-service";
import * as orgService from "@/server/services/organization-service";
import * as flagService from "@/server/services/feature-flag-service";
import {
  exportActivity,
  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("audit-check", "growth");
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("activity audit behaviour", () => {
  it("records every action once, with actor, project, time and details", async () => {
    const when = "2026-04-01T12:00:00.000Z";
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Audited" }),
    );

    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "Audited title",
    });
    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_progress",
    });
    await issueService.assignIssue(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "hello",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "hello edited",
    });
    await commentService.deleteComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      commentId: comment.id,
    });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    await projectService.updateProject(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      description: "notes",
    });
    const archivedProject = await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    await projectService.restoreProject(
      tenant.actors.admin,
      tenant.org.id,
      archivedProject.id,
    );

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: (
        await memberService.listMembers(tenant.actors.owner, {
          orgId: tenant.org.id,
          limit: 20,
          cursor: null,
        })
      ).items.find((member) => member.userId === tenant.userIds.viewer)!.id,
    });

    await orgService.updateOrganization(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Renamed",
    });

    await flagService.toggleFlag(tenant.actors.admin, {
      orgId: tenant.org.id,
      flag: "public_projects",
      enabled: true,
    });

    const page = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });
    const actions = page.items.map((event) => event.action);
    for (const action of [
      "issue.created",
      "issue.updated",
      "issue.status_changed",
      "issue.assigned",
      "issue.archived",
      "comment.created",
      "comment.updated",
      "comment.deleted",
      "project.updated",
      "project.archived",
      "project.restored",
      "member.removed",
      "organization.updated",
      "flag.toggled",
    ]) {
      expect(actions.filter((value) => value === action)).toEqual([action]);
    }

    const assigned = page.items.find((event) => event.action === "issue.assigned");
    expect(assigned?.actorId).toBe(tenant.userIds.admin);

    const projectScoped = await listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      limit: 100,
      cursor: null,
    });
    const scopedActions = projectScoped.items.map((event) => event.action).sort();
    expect(scopedActions).toEqual(
      [
        "comment.created",
        "comment.deleted",
        "comment.updated",
        "issue.archived",
        "issue.assigned",
        "issue.created",
        "issue.status_changed",
        "issue.updated",
        "project.archived",
        "project.restored",
        "project.updated",
      ].sort(),
    );
    expect(
      projectScoped.items.every((event) => event.projectId === tenant.project.id),
    ).toBe(true);

    const status = page.items.find((event) => event.action === "issue.status_changed");
    expect(status?.metadata).toMatchObject({ from: "backlog", to: "in_progress" });

    const json = await exportActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      since: page.items.at(-1)!.occurredAt,
      until: page.items[0]!.occurredAt,
      format: "json",
    });
    const parsed = JSON.parse(json) as Array<{ metadata: { from?: string } }>;
    expect(parsed.length).toBe(page.total);
    expect(parsed.some((row) => row.metadata.from === "backlog")).toBe(true);

    const instant = status!.occurredAt;
    const atInstant = await exportActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      since: instant,
      until: instant,
      format: "json",
    });
    const instantRows = JSON.parse(atInstant) as Array<{ action: string }>;
    expect(instantRows.some((row) => row.action === "issue.status_changed")).toBe(true);

    await expect(
      exportActivity(tenant.actors.admin, {
        orgId: tenant.org.id,
        since: "2026-05-02T00:00:00.000Z" as typeof instant,
        until: "2026-05-01T00:00:00.000Z" as typeof instant,
        format: "json",
      }),
    ).rejects.toThrow(/ends before/);

    void when;
    void toIsoTimestamp;
  });

  it("dates a late trial downgrade at the period end", async () => {
    const end = "2026-02-01T00:00:00.000Z";
    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription).not.toBeNull();
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "growth", "monthly");
    const dbModule = await import("@/server/db");
    const { subscriptions } = dbModule;
    const { eq } = await import("drizzle-orm");
    dbModule
      .getDb()
      .update(subscriptions)
      .set({ status: "trialing", plan: "growth", currentPeriodEnd: end })
      .where(eq(subscriptions.orgId, tenant.org.id))
      .run();

    await runTrialExpiryJob(new Date("2026-08-01T00:00:00.000Z"));

    const page = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["billing.plan_changed"],
      since: end as never,
      until: end as never,
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]?.occurredAt).toBe(end);
    expect(page.items[0]?.metadata).toMatchObject({ from: "growth", to: "free" });
  });
});

